-- STEP 3: Add FK columns to entities table
-- ============================================
ALTER TABLE entities ADD COLUMN IF NOT EXISTS sector_id INTEGER REFERENCES sectors(sector_id);
ALTER TABLE entities ADD COLUMN IF NOT EXISTS subsector_id INTEGER REFERENCES subsectors(subsector_id);
